def fill_gaps(grid, foreground, background, fill_color=2):
    """Fill gaps between foreground cells with fill_color"""
    result = [row[:] for row in grid]
    for row_idx in range(len(result)):
        row_len = len(result[row_idx])
        i = 0
        while i < row_len:
            # Look back for foreground
            last_fg = -1
            for j in range(max(0, i-10), i):
                if result[row_idx][j] == foreground:
                    last_fg = j
                    break

            # Look forward for foreground
            next_fg = -1
            for j in range(i+1, min(i+10, row_len)):
                if result[row_idx][j] == foreground:
                    next_fg = j
                    break

            if last_fg >= 0 and next_fg > i and next_fg > last_fg:
                for k in range(last_fg + 1, next_fg):
                    if result[row_idx][k] == background:
                        result[row_idx][k] = fill_color

            i += 1
    return result

